### Basic Comprehensions

```python
# Square numbers as dictionary
squares = {x: x**2 for x in range(1, 6)}
print(squares)  # {1: 1, 2: 4, 3: 9, 4: 16, 5: 25}

# String length dictionary
words = ['apple', 'banana', 'cherry']
lengths = {word: len(word) for word in words}
print(lengths)  # {'apple': 5, 'banana': 6, 'cherry': 6}

# Conditional comprehensions
numbers = range(1, 11)
even_squares = {x: x**2 for x in numbers if x % 2 == 0}
print(even_squares)  # {2: 4, 4: 16, 6: 36, 8: 64, 10: 100}

# Transform existing dictionary
prices = {'apple': 1.5, 'banana': 0.8, 'orange': 2.0}
discounted = {item: price * 0.9 for item, price in prices.items()}
print(discounted)  # {'apple': 1.35, 'banana': 0.72, 'orange': 1.8}
```

### Advanced Comprehensions

```python
# Nested comprehension for matrix transformation
matrix = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
indexed_matrix = {i: {j: matrix[i][j] for j in range(len(matrix[i]))}
                  for i in range(len(matrix))}

# Multiple conditions
students_data = [
    ('Alice', 85, 'A'), ('Bob', 72, 'B'), ('Charlie', 95, 'A'), ('Diana', 68, 'C')
]
honor_students = {name: grade for name, score, grade in students_data
                  if score >= 80 and grade == 'A'}

# Using zip in comprehensions
keys = ['name', 'age', 'city']
values = ['John', 30, 'NYC']
person = {k: v for k, v in zip(keys, values)}
```

