### Example 1: Student Management System

```python
class StudentManagementSystem:
    def __init__(self):
        self.students = {}
        self.courses = defaultdict(set)

    def add_student(self, student_id, name, email):
        self.students[student_id] = {
            'name': name,
            'email': email,
            'enrolled_courses': set(),
            'grades': {}
        }

    def enroll_student(self, student_id, course):
        if student_id in self.students:
            self.students[student_id]['enrolled_courses'].add(course)
            self.courses[course].add(student_id)

    def add_grade(self, student_id, course, grade):
        if student_id in self.students:
            self.students[student_id]['grades'][course] = grade

    def get_student_gpa(self, student_id):
        if student_id not in self.students:
            return None

        grades = self.students[student_id]['grades'].values()
        return sum(grades) / len(grades) if grades else 0.0

    def get_course_average(self, course):
        students_in_course = [
            self.students[sid]['grades'].get(course, 0)
            for sid in self.courses[course]
            if course in self.students[sid]['grades']
        ]
        return sum(students_in_course) / len(students_in_course) if students_in_course else 0.0

    def get_honor_students(self, min_gpa=3.5):
        return {
            sid: data for sid, data in self.students.items()
            if self.get_student_gpa(sid) >= min_gpa
        }

# Usage example
sms = StudentManagementSystem()
sms.add_student('S001', 'Alice Johnson', 'alice@email.com')
sms.add_student('S002', 'Bob Smith', 'bob@email.com')

sms.enroll_student('S001', 'Math')
sms.enroll_student('S001', 'Science')
sms.add_grade('S001', 'Math', 95)
sms.add_grade('S001', 'Science', 87)

print(f"Alice's GPA: {sms.get_student_gpa('S001'):.2f}")
```

### Example 2: Configuration Management

```python
import json
from pathlib import Path
from typing import Any, Dict

class ConfigManager:
    def __init__(self, config_file: str = 'config.json'):
        self.config_file = Path(config_file)
        self.config = {}
        self.defaults = {
            'database': {
                'host': 'localhost',
                'port': 5432,
                'name': 'myapp'
            },
            'api': {
                'host': '0.0.0.0',
                'port': 8000,
                'debug': False
            },
            'logging': {
                'level': 'INFO',
                'file': 'app.log'
            }
        }
        self.load_config()

    def load_config(self):
        """Load configuration from file, falling back to defaults"""
        try:
            if self.config_file.exists():
                with open(self.config_file, 'r') as f:
                    file_config = json.load(f)
                    self.config = self._merge_configs(self.defaults, file_config)
            else:
                self.config = self.defaults.copy()
        except json.JSONDecodeError:
            print("Invalid config file, using defaults")
            self.config = self.defaults.copy()

    def _merge_configs(self, default: Dict, override: Dict) -> Dict:
        """Recursively merge configuration dictionaries"""
        result = default.copy()
        for key, value in override.items():
            if key in result and isinstance(result[key], dict) and isinstance(value, dict):
                result[key] = self._merge_configs(result[key], value)
            else:
                result[key] = value
        return result

    def get(self, key_path: str, default=None):
        """Get configuration value using dot notation (e.g., 'database.host')"""
        keys = key_path.split('.')
        value = self.config

        for key in keys:
            if isinstance(value, dict) and key in value:
                value = value[key]
            else:
                return default
        return value

    def set(self, key_path: str, value: Any):
        """Set configuration value using dot notation"""
        keys = key_path.split('.')
        config_ref = self.config

        for key in keys[:-1]:
            if key not in config_ref:
                config_ref[key] = {}
            config_ref = config_ref[key]

        config_ref[keys[-1]] = value

    def save_config(self):
        """Save current configuration to file"""
        with open(self.config_file, 'w') as f:
            json.dump(self.config, f, indent=2)

# Usage
config = ConfigManager()
print(config.get('database.host'))  # 'localhost'
config.set('database.host', 'prod-server.com')
config.save_config()
```

### Example 3: Caching System

```python
import time
from functools import wraps
from typing import Any, Callable

class Cache:
    def __init__(self, max_size: int = 100, ttl: int = 300):
        self.max_size = max_size
        self.ttl = ttl  # Time to live in seconds
        self._cache = {}
        self._timestamps = {}
        self._access_order = []  # For LRU

    def _is_expired(self, key: str) -> bool:
        """Check if cache entry is expired"""
        if key not in self._timestamps:
            return True
        return time.time() - self._timestamps[key] > self.ttl

    def _evict_lru(self):
        """Evict least recently used item"""
        if self._access_order:
            lru_key = self._access_order.pop(0)
            self._cache.pop(lru_key, None)
            self._timestamps.pop(lru_key, None)

    def get(self, key: str) -> Any:
        """Get value from cache"""
        if key in self._cache and not self._is_expired(key):
            # Move to end (most recently used)
            self._access_order.remove(key)
            self._access_order.append(key)
            return self._cache[key]

        # Clean up expired entry
        if key in self._cache:
            self._cache.pop(key)
            self._timestamps.pop(key)
            self._access_order.remove(key)

        return None

    def set(self, key: str, value: Any):
        """Set value in cache"""
        # Remove if already exists
        if key in self._cache:
            self._access_order.remove(key)

        # Evict if at capacity
        elif len(self._cache) >= self.max_size:
            self._evict_lru()

        # Add new entry
        self._cache[key] = value
        self._timestamps[key] = time.time()
        self._access_order.append(key)

    def clear(self):
        """Clear all cache"""
        self._cache.clear()
        self._timestamps.clear()
        self._access_order.clear()

    def stats(self) -> dict:
        """Get cache statistics"""
        total_entries = len(self._cache)
        expired_entries = sum(1 for key in self._cache if self._is_expired(key))

        return {
            'total_entries': total_entries,
            'valid_entries': total_entries - expired_entries,
            'expired_entries': expired_entries,
            'max_size': self.max_size,
            'hit_ratio': getattr(self, '_hits', 0) / max(getattr(self, '_requests', 1), 1)
        }

def cached(cache_instance: Cache = None, key_func: Callable = None):
    """Decorator to cache function results"""
    if cache_instance is None:
        cache_instance = Cache()

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Generate cache key
            if key_func:
                cache_key = key_func(*args, **kwargs)
            else:
                cache_key = f"{func.__name__}:{hash(str(args) + str(sorted(kwargs.items())))}"

            # Try to get from cache
            result = cache_instance.get(cache_key)
            if result is not None:
                return result

            # Compute and cache result
            result = func(*args, **kwargs)
            cache_instance.set(cache_key, result)
            return result

        wrapper.cache = cache_instance
        return wrapper
    return decorator

# Usage example
@cached(Cache(max_size=50, ttl=60))
def expensive_computation(n):
    """Simulate expensive computation"""
    time.sleep(1)  # Simulate delay
    return sum(i**2 for i in range(n))

# First call - computed
result1 = expensive_computation(100)  # Takes ~1 second

# Second call - from cache
result2 = expensive_computation(100)  # Nearly instant
```

### Code Style and Conventions

```python
# Good: Clear, descriptive keys
user_preferences = {
    'theme': 'dark',
    'language': 'python',
    'auto_save': True
}

# Avoid: Unclear abbreviations
# user_prefs = {'thm': 'dark', 'lng': 'python', 'as': True}

# Good: Use get() with meaningful defaults
def get_user_setting(settings, key):
    defaults = {
        'theme': 'light',
        'language': 'english',
        'notifications': True
    }
    return settings.get(key, defaults.get(key, None))

# Good: Type hints for dictionary parameters
from typing import Dict, List, Optional

def process_user_data(users: Dict[str, Dict[str, any]]) -> List[str]:
    return [user['name'] for user in users.values() if user.get('active', False)]
```

### Error Handling

```python
def safe_dictionary_operations():
    data = {'a': 1, 'b': 2}

    # Safe key access
    try:
        value = data['c']
    except KeyError:
        value = None

    # Better: use get()
    value = data.get('c', 0)  # Default to 0

    # Safe nested access
    def safe_nested_get(d, *keys):
        for key in keys:
            try:
                d = d[key]
            except (KeyError, TypeError):
                return None
        return d

    # Validate dictionary structure
    def validate_user_dict(user_dict):
        required_keys = {'name', 'email', 'age'}
        if not isinstance(user_dict, dict):
            raise ValueError("Expected dictionary")

        missing_keys = required_keys - set(user_dict.keys())
        if missing_keys:
            raise ValueError(f"Missing required keys: {missing_keys}")

        return True
```

### Memory Efficiency

```python
# Use dictionary comprehensions instead of loops when appropriate
numbers = range(1000)

# Memory efficient
squares = {x: x**2 for x in numbers if x % 2 == 0}

# Less efficient
# squares = {}
# for x in numbers:
#     if x % 2 == 0:
#         squares[x] = x**2

# Use generators for large datasets
def generate_user_dict(users_data):
    """Generator for processing large user datasets"""
    for user_data in users_data:
        yield {
            'id': user_data[0],
            'name': user_data[1].strip().title(),
            'email': user_data[2].lower(),
            'age': int(user_data[3]) if user_data[3].isdigit() else None
        }

# Use __slots__ in classes that create many dictionary-like objects
class OptimizedUser:
    __slots__ = ['name', 'email', 'age']

    def __init__(self, name, email, age):
        self.name = name
        self.email = email
        self.age = age
```

### Testing Dictionaries

```python
import unittest

class TestDictionaryOperations(unittest.TestCase):
    def setUp(self):
        self.sample_dict = {'a': 1, 'b': 2, 'c': 3}

    def test_key_existence(self):
        self.assertIn('a', self.sample_dict)
        self.assertNotIn('d', self.sample_dict)

    def test_value_types(self):
        for value in self.sample_dict.values():
            self.assertIsInstance(value, int)

    def test_dictionary_equality(self):
        expected = {'a': 1, 'b': 2, 'c': 3}
        self.assertEqual(self.sample_dict, expected)

    def test_dictionary_operations(self):
        # Test copy doesn't affect original
        copy_dict = self.sample_dict.copy()
        copy_dict['d'] = 4
        self.assertNotIn('d', self.sample_dict)

        # Test update operation
        self.sample_dict.update({'d': 4, 'e': 5})
        self.assertEqual(len(self.sample_dict), 5)

if __name__ == '__main__':
    unittest.main()
```
